#!/bin/bash
# Makes "build/True Liquid Glass Installer.pkg" from a built app bundle.
#   Scripts/make_installer.sh "<path to True Liquid Glass.app>" "<architectures>"
# The welcome/conclusion pages (10 languages) are generated by the app itself, from the
# same translations it uses in its own windows.
set -euo pipefail
cd "$(dirname "$0")/.."

APP="${1:?usage: make_installer.sh <app> <archs>}"
ARCHS="${2:-arm64}"
PKG_ID="nl.liquidvenster.pkg"
OUTPUT="build/True Liquid Glass Installer.pkg"
EXECUTABLE="$APP/Contents/MacOS/TrueLiquidGlass"

fail() { echo "❌ Installatiepakket: $*" >&2; exit 1; }

[[ -d "$APP" && -x "$EXECUTABLE" ]] || fail "app niet gevonden: $APP"
codesign --verify --strict "$APP" || fail "handtekening van de app is ongeldig"
VERSION="$(plutil -extract CFBundleShortVersionString raw "$APP/Contents/Info.plist")"
HOST_ARCHS="$(echo "$ARCHS" | tr ' ' ',')"

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
mkdir -p "$WORK/root/Applications" "$WORK/scripts" "$WORK/resources"

echo "▸ Installatiepakket maken (versie $VERSION, $HOST_ARCHS)…"
ditto "$APP" "$WORK/root/Applications/True Liquid Glass.app"

# Not relocatable: otherwise Installer may "update" another copy with the same bundle
# identifier (for example the one in build/) instead of installing into /Applications.
pkgbuild --analyze --root "$WORK/root" "$WORK/component.plist" >/dev/null
plutil -replace 0.BundleIsRelocatable -bool NO "$WORK/component.plist"
[[ "$(plutil -extract 0.BundleIsRelocatable raw "$WORK/component.plist")" == "false" ]] || fail "component.plist"

cp Installer/scripts/preinstall Installer/scripts/postinstall "$WORK/scripts/"
chmod 755 "$WORK/scripts/preinstall" "$WORK/scripts/postinstall"
sh -n "$WORK/scripts/preinstall" && sh -n "$WORK/scripts/postinstall" || fail "fout in installatiescripts"

pkgbuild --root "$WORK/root" --component-plist "$WORK/component.plist" --scripts "$WORK/scripts" \
    --identifier "$PKG_ID" --version "$VERSION" --install-location / "$WORK/TrueLiquidGlass.pkg" >/dev/null \
    || fail "pkgbuild mislukt"

"$EXECUTABLE" --installer-pages "$WORK/resources" || fail "uitlegpagina's maken mislukt"
for lang in en nl de fr es pt-BR it ru zh-Hans ja; do
    for page in welcome conclusion; do
        [[ -s "$WORK/resources/$lang.lproj/$page.html" ]] || fail "$lang.lproj/$page.html ontbreekt"
    done
done
if [[ -f build/AppIcon.icns ]]; then
    sips -s format png build/AppIcon.icns --resampleWidth 160 --out "$WORK/resources/background.png" >/dev/null \
        || fail "achtergrondafbeelding maken mislukt"
fi

sed -e "s/__VERSION__/$VERSION/" -e "s/__ARCHS__/$HOST_ARCHS/" Installer/Distribution.xml > "$WORK/Distribution.xml"
[[ -f "$WORK/resources/background.png" ]] || sed -i '' '/<background/d' "$WORK/Distribution.xml"

rm -f "$OUTPUT"
productbuild --distribution "$WORK/Distribution.xml" --resources "$WORK/resources" --package-path "$WORK" \
    "$OUTPUT" >/dev/null || fail "productbuild mislukt"

# Sanity checks on the result.
pkgutil --expand "$OUTPUT" "$WORK/check" || fail "pakket kan niet worden uitgepakt"
[[ -f "$WORK/check/TrueLiquidGlass.pkg/Payload" && -x "$WORK/check/TrueLiquidGlass.pkg/Scripts/postinstall" ]] \
    || fail "pakket mist payload of scripts"
echo "✅ Installatiepakket: $OUTPUT ($(du -h "$OUTPUT" | cut -f1))"
